}

#include <stdio.h>
int g;
void f(void) { g += 5; }
int main(void) {
    f(); f();
    printf("%d\n", g);
    return 0;
}

void counter(void) {
    static int n = 0;   /* 처음 한 번만 초기화된다 */
    n++;
    printf("%d ", n);
}

counter(); counter(); counter();   /* 1 2 3 */

void counter2(void) {
    int n = 0;    /* static 없음 — 매번 새로 만들어진다 */
    n++;
    printf("%d ", n);
}

counter2(); counter2(); counter2();   /* 1 1 1 */

#include <stdio.h>
void f(void) {
    static int s = 0;
    int a = 0;
    s++; a++;
    printf("%d %d\n", s, a);
}
int main(void) { f(); f(); return 0; }

int *bad(void) {
    int x = 42;
    return &x;      /* 위험: x 는 곧 사라진다 */
}

int *ok(void) {
    static int x = 42;
    return &x;      /* 안전: 데이터 영역에 있어 사라지지 않는다 */
}

